#[derive(Debug, Clone)]
pub enum IRInstr {
    /// ty, dst, lhs, rhs
    Add(IRType, IRValue, IRValue, IRValue),
    /// ty, dst
    Alloca(IRType, IRValue),
    /// val, truebb, falsebb
    Br(IRValue, IRLabel, IRLabel),
    /// ty, dst, callee, args
    Call(IRType, IRValue, String, SmallVec<[IRValue; 4]>),
    /// s
    Comment(String),
    /// ty, dst, rs1
    Copy(IRType, IRValue, IRValue),
    /// dst, base, elem_ty, idx
    Getaddr(IRValue, IRValue, IRType, IRValue),
    /// cmp, ty, dst, lhs, rhs
    Icmp(CmpOp, IRType, IRValue, IRValue, IRValue),
    /// to
    Jmp(IRLabel),
    /// ty, ptr, dst
    Load(IRType, IRValue, IRValue),
    /// ty, val
    Ret(IRType, IRValue),
    ///
    Retv,
    /// ty, dst, lhs, rhs
    Sdiv(IRType, IRValue, IRValue, IRValue),
    /// to_ty, dst, from_ty, rs1
    Sext(IRType, IRValue, IRType, IRValue),
    /// ty, dst, lhs, rhs
    Smul(IRType, IRValue, IRValue, IRValue),
    /// ty, ptr, rs1
    Store(IRType, IRValue, IRValue),
    /// ty, dst, lhs, rhs
    Sub(IRType, IRValue, IRValue, IRValue),
    /// to_ty, dst, from_ty, rs1
    Trunc(IRType, IRValue, IRType, IRValue),
    /// ty, dst, lhs, rhs
    Udiv(IRType, IRValue, IRValue, IRValue),
    /// ty, dst, lhs, rhs
    Umul(IRType, IRValue, IRValue, IRValue),
    /// to_ty, dst, from_ty, rs1
    Zext(IRType, IRValue, IRType, IRValue),
}

impl std::fmt::Display for IRInstr {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Add(ty, dst, lhs, rhs) => f.write_fmt(format_args!("{dst} = add {ty}, {lhs}, {rhs}")),
            Alloca(ty, dst) => f.write_fmt(format_args!("{dst} = alloca {ty}")),
            Br(val, truebb, falsebb) => f.write_fmt(format_args!("br {val}, {truebb}, {falsebb}")),
            Call(ty, dst, callee, args) => {
                let args_str = args
                    .iter()
                    .map(|s| s.to_string())
                    .collect::<Vec<_>>()
                    .join(",");
                f.write_fmt(format_args!("{dst} = {callee}({args_str})"))
            }
            Comment(s) => f.write_fmt(format_args!("; {s}")),
            Copy(ty, dst, rs1) => f.write_fmt(format_args!("{dst} = copy {ty}, {rs1}")),
            Getaddr(dst, base, elem_ty, idx) => f.write_fmt(format_args!(
                "{dst} = getaddr {base} offset by {elem_ty}, {idx}"
            )),
            Icmp(cmp, ty, dst, lhs, rhs) => {
                f.write_fmt(format_args!("{dst} = icmp {cmp} {ty}, {lhs}, {rhs}"))
            }
            Jmp(to) => f.write_fmt(format_args!("jmp {to}")),
            Load(ty, ptr, dst) => f.write_fmt(format_args!("{dst} = load {ty} from {ptr}")),
            Ret(ty, val) => f.write_fmt(format_args!("ret {ty}, {val}")),
            Retv => f.write_fmt(format_args!("retv")),
            Sdiv(ty, dst, lhs, rhs) => f.write_fmt(format_args!("{dst} = sdiv {ty}, {lhs}, {rhs}")),
            Sext(to_ty, dst, from_ty, rs1) => {
                f.write_fmt(format_args!("{dst} = sext {from_ty} {rs1} to {to_ty}"))
            }
            Smul(ty, dst, lhs, rhs) => f.write_fmt(format_args!("{dst} = smul {ty}, {lhs}, {rhs}")),
            Store(ty, ptr, rs1) => f.write_fmt(format_args!("store {ty} {rs1} into {ptr}")),
            Sub(ty, dst, lhs, rhs) => f.write_fmt(format_args!("{dst} = sub {ty}, {lhs}, {rhs}")),
            Trunc(to_ty, dst, from_ty, rs1) => {
                f.write_fmt(format_args!("{dst} = trunc {from_ty} {rs1} to {to_ty}"))
            }
            Udiv(ty, dst, lhs, rhs) => f.write_fmt(format_args!("{dst} = udiv {ty}, {lhs}, {rhs}")),
            Umul(ty, dst, lhs, rhs) => f.write_fmt(format_args!("{dst} = umul {ty}, {lhs}, {rhs}")),
            Zext(to_ty, dst, from_ty, rs1) => {
                f.write_fmt(format_args!("{dst} = zext {from_ty} {rs1} to {to_ty}"))
            }
        }
    }
}

impl InstructionTrait for IRInstr {
    type Val = IRValue;

    fn uses(&self) -> SmallVec<[&Self::Val; 4]> {
        match self {
            Add(ty, dst, lhs, rhs) => smallvec![lhs, rhs],
            Alloca(ty, dst) => smallvec![],
            Br(val, truebb, falsebb) => smallvec![val],
            Call(ty, dst, callee, args) => args.iter().collect(),
            Comment(s) => smallvec![],
            Copy(ty, dst, rs1) => smallvec![rs1],
            Getaddr(dst, base, elem_ty, idx) => smallvec![base, idx],
            Icmp(cmp, ty, dst, lhs, rhs) => smallvec![lhs, rhs],
            Jmp(to) => smallvec![],
            Load(ty, ptr, dst) => smallvec![ptr],
            Ret(ty, val) => smallvec![val],
            Retv => smallvec![],
            Sdiv(ty, dst, lhs, rhs) => smallvec![lhs, rhs],
            Sext(to_ty, dst, from_ty, rs1) => smallvec![rs1],
            Smul(ty, dst, lhs, rhs) => smallvec![lhs, rhs],
            Store(ty, ptr, rs1) => smallvec![ptr, rs1],
            Sub(ty, dst, lhs, rhs) => smallvec![lhs, rhs],
            Trunc(to_ty, dst, from_ty, rs1) => smallvec![rs1],
            Udiv(ty, dst, lhs, rhs) => smallvec![lhs, rhs],
            Umul(ty, dst, lhs, rhs) => smallvec![lhs, rhs],
            Zext(to_ty, dst, from_ty, rs1) => smallvec![rs1],
        }
    }

    fn defs(&self) -> SmallVec<[&Self::Val; 4]> {
        match self {
            Add(ty, dst, lhs, rhs) => smallvec![dst],
            Alloca(ty, dst) => smallvec![dst],
            Br(val, truebb, falsebb) => smallvec![],
            Call(ty, dst, callee, args) => smallvec![dst],
            Comment(s) => smallvec![],
            Copy(ty, dst, rs1) => smallvec![dst],
            Getaddr(dst, base, elem_ty, idx) => smallvec![dst],
            Icmp(cmp, ty, dst, lhs, rhs) => smallvec![dst],
            Jmp(to) => smallvec![],
            Load(ty, ptr, dst) => smallvec![dst],
            Ret(ty, val) => smallvec![],
            Retv => smallvec![],
            Sdiv(ty, dst, lhs, rhs) => smallvec![dst],
            Sext(to_ty, dst, from_ty, rs1) => smallvec![dst],
            Smul(ty, dst, lhs, rhs) => smallvec![dst],
            Store(ty, ptr, rs1) => smallvec![],
            Sub(ty, dst, lhs, rhs) => smallvec![dst],
            Trunc(to_ty, dst, from_ty, rs1) => smallvec![dst],
            Udiv(ty, dst, lhs, rhs) => smallvec![dst],
            Umul(ty, dst, lhs, rhs) => smallvec![dst],
            Zext(to_ty, dst, from_ty, rs1) => smallvec![dst],
        }
    }

    fn is_terminator(&self) -> bool {
        match self {
            Add(ty, dst, lhs, rhs) => false,
            Alloca(ty, dst) => false,
            Br(val, truebb, falsebb) => true,
            Call(ty, dst, callee, args) => false,
            Comment(s) => false,
            Copy(ty, dst, rs1) => false,
            Getaddr(dst, base, elem_ty, idx) => false,
            Icmp(cmp, ty, dst, lhs, rhs) => false,
            Jmp(to) => true,
            Load(ty, ptr, dst) => false,
            Ret(ty, val) => true,
            Retv => true,
            Sdiv(ty, dst, lhs, rhs) => false,
            Sext(to_ty, dst, from_ty, rs1) => false,
            Smul(ty, dst, lhs, rhs) => false,
            Store(ty, ptr, rs1) => false,
            Sub(ty, dst, lhs, rhs) => false,
            Trunc(to_ty, dst, from_ty, rs1) => false,
            Udiv(ty, dst, lhs, rhs) => false,
            Umul(ty, dst, lhs, rhs) => false,
            Zext(to_ty, dst, from_ty, rs1) => false,
        }
    }
}
